alter table public.company_settings drop constraint if exists company_settings_screen_language_supported;
alter table public.company_settings drop constraint if exists company_settings_screen_language_pair;
alter table public.company_settings drop constraint if exists company_settings_document_language_supported;
alter table public.company_settings drop constraint if exists company_settings_document_language_pair;
alter table public.user_language_preferences drop constraint if exists user_language_preferences_supported;
alter table public.user_language_preferences drop constraint if exists user_language_preferences_pair;
alter table public.company_settings add constraint company_settings_screen_language_supported check (coalesce(screen_primary_language,'en')=any(array['en','ur','ar','hi','bn','fa','tr','fr','es','de','pt','ru','zh','id','ms']::text[]) and (screen_secondary_language is null or screen_secondary_language=any(array['en','ur','ar','hi','bn','fa','tr','fr','es','de','pt','ru','zh','id','ms']::text[])) and (screen_secondary_language is null or screen_secondary_language<>screen_primary_language));
alter table public.company_settings add constraint company_settings_screen_language_pair check (coalesce(screen_language_mode,'single') in ('single','bilingual') and (coalesce(screen_language_mode,'single')='single' or (screen_secondary_language is not null and screen_secondary_language<>screen_primary_language)));
alter table public.company_settings add constraint company_settings_document_language_supported check (coalesce(document_primary_language,'en')=any(array['en','ur','ar','hi','bn','fa','tr','fr','es','de','pt','ru','zh','id','ms']::text[]) and (document_secondary_language is null or document_secondary_language=any(array['en','ur','ar','hi','bn','fa','tr','fr','es','de','pt','ru','zh','id','ms']::text[])) and (document_secondary_language is null or document_secondary_language<>document_primary_language));
alter table public.company_settings add constraint company_settings_document_language_pair check (coalesce(document_language_mode,'single') in ('single','bilingual') and (coalesce(document_language_mode,'single')='single' or (document_secondary_language is not null and document_secondary_language<>document_primary_language)));
alter table public.user_language_preferences add constraint user_language_preferences_supported check (coalesce(primary_language,'en')=any(array['en','ur','ar','hi','bn','fa','tr','fr','es','de','pt','ru','zh','id','ms']::text[]) and (secondary_language is null or secondary_language=any(array['en','ur','ar','hi','bn','fa','tr','fr','es','de','pt','ru','zh','id','ms']::text[])) and (secondary_language is null or secondary_language<>primary_language));
alter table public.user_language_preferences add constraint user_language_preferences_pair check (coalesce(screen_language_mode,'single')='single' or (secondary_language is not null and secondary_language<>primary_language));
